  ],
  "properties": {
    "ascending": {
      "description": "是否升序：true=升序 / false=降序（默认）。",
      "type": "boolean"
    },
    "cursor": {
      "description": "翻页游标。首次调用不传；翻页时回填上次响应里的 next_cursor。",
